// This code has been fully generated by an AI.
//
// Pure helpers that turn the server's map configuration (see
// internal/web/mapconfig.go) into a MapLibre style. No DOM access, so the
// module can be tested with node --test.

export const STORAGE_KEY = "myvelo.basemap";
export const OVERLAY_KEY = "myvelo.overlays";

const layerId = (id) => `base-${id}`;
const overlayLayerId = (id) => `overlay-${id}`;

/**
 * Builds a MapLibre style containing every basemap and overlay as raster
 * layer. Only the selected basemap and enabled overlays are visible; hidden
 * layers do not request tiles, so switching is instant and keeps data layers.
 */
export function buildStyle(cfg, selected, enabledOverlays = []) {
  const basemapId = cfg.basemaps.some((b) => b.id === selected) ? selected : cfg.default;
  const sources = {};
  const layers = [];
  for (const b of cfg.basemaps) {
    sources[layerId(b.id)] = rasterSource(b);
    layers.push({
      id: layerId(b.id),
      type: "raster",
      source: layerId(b.id),
      layout: { visibility: b.id === basemapId ? "visible" : "none" },
    });
  }
  for (const o of cfg.overlays ?? []) {
    sources[overlayLayerId(o.id)] = rasterSource(o);
    layers.push({
      id: overlayLayerId(o.id),
      type: "raster",
      source: overlayLayerId(o.id),
      layout: { visibility: enabledOverlays.includes(o.id) ? "visible" : "none" },
    });
  }
  return { version: 8, sources, layers };
}

function rasterSource(b) {
  return {
    type: "raster",
    tiles: b.tiles,
    tileSize: b.tileSize || 256,
    maxzoom: b.maxzoom || 19,
    attribution: b.attribution,
  };
}

/** Returns [layerId, visibility] pairs to show only the given basemap. */
export function basemapVisibility(cfg, selected) {
  return cfg.basemaps.map((b) => [layerId(b.id), b.id === selected ? "visible" : "none"]);
}

export function overlayLayer(id) {
  return overlayLayerId(id);
}

/** Bounds [[minLon, minLat], [maxLon, maxLat]] of [lon, lat] pairs, or null. */
export function bounds(coords) {
  let minLon = Infinity, minLat = Infinity, maxLon = -Infinity, maxLat = -Infinity;
  for (const [lon, lat] of coords) {
    if (lon < minLon) minLon = lon;
    if (lon > maxLon) maxLon = lon;
    if (lat < minLat) minLat = lat;
    if (lat > maxLat) maxLat = lat;
  }
  return Number.isFinite(minLon) ? [[minLon, minLat], [maxLon, maxLat]] : null;
}
